"use client";

import { useState } from "react";
import { SaturatorPanel } from "@/components/audio-ui/devices/saturator/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import {
  type SaturatorState,
  saturatorDevice,
} from "@/components/audio-ui/devices/saturator/device";
import { createSaturatorEngine } from "@/components/audio-ui/devices/saturator/engine";

const MASTER_VOLUME = 0.7;

/**
 * A saturator you can plug in: its state, a panel that draws its transfer
 * curve and an engine that plays it, each its own file and none knowing the
 * others. Play the loop, pick a curve and turn the drive: the curve bends as
 * the sound does.
 */
export function BlockSaturator() {
  const [state, setState] = useState<SaturatorState>(() =>
    saturatorDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    create: createSaturatorEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-4xl h-full w-full min-w-0">
      <SaturatorPanel onValueChange={setState} value={state} />
    </div>
  );
}
